  "own_solution": {
    "law": "For Newtonian gravity, energy conservation gives (1/2) v_esc^2 - GM/R = 0, hence v_esc = sqrt(2GM/R). Substituting the numerical values gives 4, but the stated mass unit prevents interpreting this as a physical speed.",
    "assumptions": [
      "The intended toy model uses Newtonian gravity for an isolated, spherically symmetric planet.",
      "Obtaining 4 m/s requires correcting the planet's mass to 8.0 kg and interpreting G as 1.0 m^3 kg^-1 s^-2."
    ],
    "answer": null,
    "unit": "m/s"
  },
  "stratum_assignments": {},
  "validity": "invalid",
